  1412	cli_vba_inflate(int fd, off_t offset, size_t *size)
  1413	{
  1414	    unsigned int pos, shift, mask, distance, clean;
  1415	    uint8_t flag;
  1416	    uint16_t token;
  1417	    blob *b;
  1418	    unsigned char buffer[VBA_COMPRESSION_WINDOW];
  1419	
  1420	    if (fd < 0)
  1421	        return NULL;
  1422	
  1423	    b = blobCreate();
  1424	
  1425	    if (b == NULL)
