  1427	
  1428	    memset(buffer, 0, sizeof(buffer));
  1429	    lseek(fd, offset + 3, SEEK_SET); /* 1byte ?? , 2byte length ?? */
  1430	    clean = TRUE;
  1431	    pos   = 0;
  1432	
  1433	    while (cli_readn(fd, &flag, 1) == 1) {
  1434	        for (mask = 1; mask < 0x100; mask <<= 1) {
  1435	            unsigned int winpos = pos % VBA_COMPRESSION_WINDOW;
  1436	            if (flag & mask) {
  1437	                uint16_t len;
  1438	                unsigned int srcpos;
  1439	
  1440	                if (!read_uint16(fd, &token, FALSE)) {
  1441	                    blobDestroy(b);
  1442	                    if (size)
  1443	                        *size = 0;
  1444	                    return NULL;
  1445	                }
  1446	                shift    = 12 - (winpos > 0x10) - (winpos > 0x20) - (winpos > 0x40) - (winpos > 0x80) - (winpos > 0x100) - (winpos > 0x200) - (winpos > 0x400) - (winpos > 0x800);
  1447	                len      = (uint16_t)((token & ((1 << shift) - 1)) + 3);
  1448	                distance = token >> shift;
  1449	
  1450	                srcpos = pos - distance - 1;
  1451	                if ((((srcpos + len) % VBA_COMPRESSION_WINDOW) < winpos) &&
  1452	                    ((winpos + len) < VBA_COMPRESSION_WINDOW) &&
  1453	                    (((srcpos % VBA_COMPRESSION_WINDOW) + len) < VBA_COMPRESSION_WINDOW) &&
  1454	                    (len <= VBA_COMPRESSION_WINDOW)) {
  1455	                    srcpos %= VBA_COMPRESSION_WINDOW;
  1456	                    memcpy(&buffer[winpos], &buffer[srcpos],
  1457	                           len);
  1458	                    pos += len;
  1459	                } else
  1460	                    while (len-- > 0) {
  1461	                        srcpos                                 = (pos - distance - 1) % VBA_COMPRESSION_WINDOW;
  1462	                        buffer[pos++ % VBA_COMPRESSION_WINDOW] = buffer[srcpos];
  1463	                    }
  1464	            } else {
  1465	                if ((pos != 0) && (winpos == 0) && clean) {
  1466	                    if (cli_readn(fd, &token, 2) != 2) {
  1467	                        blobDestroy(b);
  1468	                        if (size)
  1469	                            *size = 0;
  1470	                        return NULL;
  1471	                    }
  1472	                    (void)blobAddData(b, buffer, VBA_COMPRESSION_WINDOW);
  1473	                    clean = FALSE;
  1474	                    break;
  1475	                }
  1476	                if (cli_readn(fd, &buffer[winpos], 1) == 1)
  1477	                    pos++;
  1478	            }
  1479	            clean = TRUE;
  1480	        }
  1481	    }
  1482	
  1483	    if (blobAddData(b, buffer, pos % VBA_COMPRESSION_WINDOW) < 0) {
  1484	        blobDestroy(b);
  1485	        if (size)
  1486	            *size = 0;
  1487	        return NULL;
  1488	    }
  1489	
  1490	    if (size)
  1491	        *size = blobGetDataSize(b);
  1492	    return (unsigned char *)blobToMem(b);
  1493	}
